import { CELESTIAL_ENGINE_CONFIG } from "../../values/celestialEngines.js";
import { enumerateDiscTiles } from "./CelestialActivationBudget.js";

function cardinal(direction, fallback = { x: 1, y: 0 }) {
  const x = Number(direction?.x) || 0;
  const y = Number(direction?.y) || 0;
  if (Math.abs(y) > Math.abs(x)) return { x: 0, y: Math.sign(y) };
  if (x !== 0) return { x: Math.sign(x), y: 0 };
  return fallback;
}

/** Permanent low-power follower unlocked by the Hollow Sun apex node. */
export class HollowSunCompanion {
  constructor(options) {
    Object.assign(this, options);
    const anchor = this.getAnchor();
    this.direction = { x: 1, y: 0 };
    this.x = anchor.x + this.definition.passiveHollowFollowDistanceTiles * this.tileSize;
    this.y = anchor.y;
    this.digs = 0;
    this.pulses = 0;
    this.impacts = 0;
    this.active = true;
    this._createVisual();
  }

  _createVisual() {
    const size = this.definition.passiveHollowDisplaySizePx;
    const depth = CELESTIAL_ENGINE_CONFIG.fx.worldDepth;
    this.core = this.scene.add.circle(this.x, this.y, size * 0.19, 0x000000, 1)
      .setDepth(depth - 1);
    this.sprite = this.scene.add.image(this.x, this.y, this.assetKey)
      .setDisplaySize(size, size)
      .setBlendMode(Phaser.BlendModes.ADD)
      .setDepth(depth);
    this.orbit = this.scene.add.circle(this.x, this.y, size * 0.34, 0x000000, 0)
      .setStrokeStyle(2, 0xb985ff, 0.48)
      .setBlendMode(Phaser.BlendModes.ADD)
      .setDepth(depth - 2);
    this.scene.tweens.add({
      targets: this.orbit,
      scale: 1.38,
      alpha: 0.12,
      duration: 920,
      yoyo: true,
      repeat: -1,
      ease: "Sine.inOut",
    });
  }

  update(nowMs, deltaMs) {
    if (!this.active) return;
    const dt = Math.min(0.05, Math.max(0, Number(deltaMs) || 0) / 1000);
    const anchor = this.getAnchor();
    const lead = this.definition.passiveHollowFollowDistanceTiles * this.tileSize;
    const desiredX = anchor.x + this.direction.x * lead;
    const desiredY = anchor.y + this.direction.y * lead;
    const dx = desiredX - this.x;
    const dy = desiredY - this.y;
    const distance = Math.hypot(dx, dy);
    const speed = this.definition.passiveHollowFollowSpeedTilesPerSecond * this.tileSize;
    if (distance > 0 && speed > 0) {
      const travel = Math.min(distance, speed * dt);
      this.x += dx / distance * travel;
      this.y += dy / distance * travel;
    }
    for (const visual of [this.sprite, this.core, this.orbit]) {
      visual.setPosition(this.x, this.y);
    }
    this.sprite.angle += CELESTIAL_ENGINE_CONFIG.fx.hollowRotationDegPerSecond * dt;
    this.core.setScale(1 + Math.sin(nowMs / 210) * 0.06);
  }

  onPlayerDig(direction, nowMs) {
    if (!this.active) return false;
    this.direction = cardinal(direction, this.direction);
    this.digs += 1;
    const every = Math.max(1, Math.floor(this.definition.passiveHollowPulseEveryDigs));
    if (this.digs % every !== 0) return false;
    this._pulse(nowMs);
    return true;
  }

  _pulse(nowMs) {
    this.pulses += 1;
    const center = this.toTile(this.x, this.y);
    const radius = this.definition.passiveHollowPulseRadiusTiles;
    const cap = Math.max(1, Math.floor(this.definition.passiveHollowPulseImpactCap));
    let pulseImpacts = 0;
    for (const tile of enumerateDiscTiles(center, radius)) {
      if (pulseImpacts >= cap) break;
      if (!this.probeTile(tile.tx, tile.ty).diggable) continue;
      pulseImpacts += 1;
      this.impacts += 1;
      this.onImpact?.(
        tile.tx,
        tile.ty,
        `companion-hollow:${this.pulses}:${this.impacts}:${tile.tx},${tile.ty}`,
        nowMs,
        this.definition.passiveHollowDamageScale,
      );
    }
    const radiusPx = Math.max(this.tileSize, radius * this.tileSize);
    const ring = this.scene.add.circle(this.x, this.y, radiusPx, 0x000000, 0)
      .setStrokeStyle(3, 0xb985ff, 0.82)
      .setBlendMode(Phaser.BlendModes.ADD)
      .setDepth(CELESTIAL_ENGINE_CONFIG.fx.worldDepth - 1)
      .setScale(0.35);
    this.scene.tweens.add({
      targets: ring,
      scale: 1.15,
      alpha: 0,
      duration: 420,
      ease: "Power2.out",
      onComplete: () => ring.destroy(),
    });
  }

  getSnapshot() {
    return {
      active: this.active,
      digs: this.digs,
      pulses: this.pulses,
      impacts: this.impacts,
      pulseEveryDigs: this.definition.passiveHollowPulseEveryDigs,
      damageScale: this.definition.passiveHollowDamageScale,
    };
  }

  destroy() {
    this.active = false;
    for (const visual of [this.sprite, this.core, this.orbit]) {
      this.scene.tweens?.killTweensOf?.(visual);
      visual?.destroy?.();
    }
  }
}

systems/celestial/StellarLanceVfx.js:
import { CELESTIAL_ENGINE_CONFIG } from "../../values/celestialEngines.js";

const STELLAR_LANCE_PALETTES = Object.freeze([
  Object.freeze({ id: "blue", impactTint: 0x8ec5ff }),
  Object.freeze({ id: "purple", impactTint: 0xffffff }),
  Object.freeze({ id: "red", impactTint: 0xff8585 }),
]);

/** Owns the authored launch, travel-state, and tile-contact VFX for Stellar Lance. */
export class StellarLanceVfx {
  constructor(options) {
    Object.assign(this, options);
    this.projectileAssetKeys = Array.isArray(options.projectileAssetKeys)
      ? options.projectileAssetKeys.filter(Boolean)
      : [];
    if (this.projectileAssetKeys.length === 0) {
      throw new Error("Stellar Lance requires the authored wave palette");
    }
    this.impactAssetKey = options.impactAssetKey
      || this.projectileAssetKeys[1]
      || this.projectileAssetKeys[0];
    this.effects = new Set();
    this.launchFlashCount = 0;
    this.stateBurstCount = 0;
    this.scheduledImpactCount = 0;
    this.impactMomentCount = 0;
  }

  get paletteCount() {
    return Math.max(1, this.projectileAssetKeys.length);
  }

  getPalette(paletteIndex) {
    return STELLAR_LANCE_PALETTES[
      Math.max(0, Number(paletteIndex) || 0) % STELLAR_LANCE_PALETTES.length
    ];
  }

  getProjectileAssetKey(paletteIndex) {
    const index = Math.max(0, Number(paletteIndex) || 0)
      % this.projectileAssetKeys.length;
    return this.projectileAssetKeys[index];
  }

  applyState(sprite, stateIndex, sizeMultiplier = 1) {
    const states = this.definition.projectileStates || [];
    const state = states[Math.max(0, Math.min(states.length - 1, stateIndex))]
      || {};
    const stateScale = (Number(state.displayScale) || 1) * sizeMultiplier;
    sprite.setDisplaySize(
      this.definition.projectileDisplayWidthPx * stateScale,
      this.definition.projectileDisplayHeightPx * stateScale,
    );
    sprite.setAlpha(Math.min(
      CELESTIAL_ENGINE_CONFIG.fx.stellarRage.projectileAlpha,
      Number(state.alpha) || 1,
    ));
    return sprite;
  }

  spawnLaunch(origin, angle, paletteIndex) {
    const cfg = CELESTIAL_ENGINE_CONFIG.fx.stellarRage;
    const image = this._createEffect(
      origin.x,
      origin.y,
      angle,
      0,
      cfg.launchFlashScale,
      cfg.launchFlashAlpha,
      paletteIndex,
    );
    this.launchFlashCount += 1;
    this._fadeEffect(image, cfg.launchFlashGrowth, cfg.launchFlashMs);
    return image;
  }

  spawnStateBurst(waypoint, angle, stateIndex, paletteIndex) {
    const cfg = CELESTIAL_ENGINE_CONFIG.fx.stellarRage;
    const image = this._createEffect(
      waypoint.tx * this.tileSize + this.tileSize / 2,
      waypoint.ty * this.tileSize + this.tileSize / 2,
      angle,
      stateIndex,
      cfg.stateBurstScale,
      cfg.stateBurstAlpha,
      paletteIndex,
    );
    this.stateBurstCount += 1;
    this._fadeEffect(image, cfg.stateBurstGrowth, cfg.stateBurstMs);
    return image;
  }

  spawnImpact(hit, paletteIndex, delayMs = 0, travelAngleDeg = 0) {
    const cfg = CELESTIAL_ENGINE_CONFIG.fx.stellarRage;
    const palette = this.getPalette(paletteIndex);
    const x = hit.tx * this.tileSize + this.tileSize / 2;
    const y = hit.ty * this.tileSize + this.tileSize / 2;
    const image = this.scene.add.image(x, y, this.impactAssetKey)
      .setBlendMode(Phaser.BlendModes.ADD)
      .setDepth(
        CELESTIAL_ENGINE_CONFIG.fx.worldDepth + cfg.transientDepthOffset + 1,
      )
      .setOrigin(cfg.projectileImpactOriginX, cfg.projectileImpactOriginY)
      .setDisplaySize(
        this.tileSize * cfg.projectileImpactDisplaySizeTiles,
        this.tileSize * cfg.projectileImpactDisplaySizeTiles,
      )
      .setAlpha(0);
    image.angle = (Number(travelAngleDeg) || 0)
      - cfg.projectileImpactAuthoredTravelAngleDeg;
    image.setTint?.(palette.impactTint);
    image.scaleX *= cfg.projectileImpactScale;
    image.scaleY *= cfg.projectileImpactScale;
    this.effects.add(image);
    this.scheduledImpactCount += 1;

    this.scene.tweens.add({
      targets: image,
      alpha: 0,
      delay: Math.max(0, Math.round(delayMs)),
      duration: 1,
      onComplete: () => {
        if (!this.effects.has(image)) return;
        image.setAlpha(cfg.projectileImpactAlpha);
        this.impactMomentCount += 1;
        this.scene.tweens.add({
          targets: image,
          scaleX: image.scaleX * cfg.projectileImpactGrowth,
          scaleY: image.scaleY * cfg.projectileImpactGrowth,
          alpha: 0,
          angle: image.angle + cfg.projectileImpactRotationDeg,
          duration: cfg.projectileImpactMs,
          ease: "Power2.out",
          onComplete: () => this._release(image),
        });
      },
    });
    return image;
  }

  _createEffect(x, y, angle, stateIndex, scale, alpha, paletteIndex) {
    const cfg = CELESTIAL_ENGINE_CONFIG.fx.stellarRage;
    const image = this.scene.add.image(
      x,
      y,
      this.getProjectileAssetKey(paletteIndex),
    ).setBlendMode(Phaser.BlendModes.ADD)
      .setDepth(CELESTIAL_ENGINE_CONFIG.fx.worldDepth + cfg.transientDepthOffset);
    image.angle = angle;
    this.applyState(image, stateIndex, scale).setAlpha(alpha);
    this.effects.add(image);
    return image;
  }

  _fadeEffect(image, growth, duration) {
    this.scene.tweens.add({
      targets: image,
      scaleX: image.scaleX * growth,
      scaleY: image.scaleY * growth,
      alpha: 0,
      duration,
      ease: "Power2.out",
      onComplete: () => this._release(image),
    });
  }

  _release(image) {
    this.effects.delete(image);
    image?.destroy?.();
  }

  getSnapshot() {
    return Object.freeze({
      liveVfxCount: this.effects.size,
      launchFlashCount: this.launchFlashCount,
      stateBurstCount: this.stateBurstCount,
      scheduledImpactCount: this.scheduledImpactCount,
      impactMomentCount: this.impactMomentCount,
      paletteIds: STELLAR_LANCE_PALETTES.map(palette => palette.id),
    });
  }

  destroy() {
    for (const effect of this.effects) {
      this.scene.tweens?.killTweensOf?.(effect);
      effect.destroy?.();
    }
    this.effects.clear();
  }
}

systems/celestial/StellarRageEngine.js:
import { CELESTIAL_ENGINE_CONFIG } from "../../values/celestialEngines.js";
import { StellarLanceVfx } from "./StellarLanceVfx.js?rev=20260903-lance-impact-v4";

const roundHundredth = value => Math.round(value * 100) / 100;

/** Save-compatible runtime for the player-facing Stellar Lance projectile buff. */
export class StellarRageEngine {
  constructor(options) {
    Object.assign(this, options);
    this.definition = this.definitionOverride
      || CELESTIAL_ENGINE_CONFIG.engines[this.budget.engineId];
    this.active = true;
    this.empowered = true;
    this.finishing = false;
    this.shotsFired = 0;
    this.projectileImpacts = 0;
    this.projectileDestroyed = 0;
    this.storedBreakCharge = 0;
    this.earnedLifetimeMs = 0;
    this.lastConsumedBreakCharge = 0;
    this.lastProjectilePalette = null;
    this.paletteHistory = [];
    this.projectiles = new Set();
    this.vfx = new StellarLanceVfx({
      scene: this.scene,
      assetKey: this.assetKey,
      projectileAssetKeys: this.projectileAssetKeys,
      impactAssetKey: this.impactAssetKey,
      definition: this.definition,
      tileSize: this.tileSize,
    });
    this._createVisual();
  }

  /** The retired spinning core/aura is deliberately absent from the player. */
  _createVisual() {
    this.playerVisualCount = 0;
  }

  update(nowMs) {
    if (!this.active || this.finishing) return;
    const ageMs = Math.max(0, Number(nowMs) - this.budget.startedAtMs);
    if (ageMs >= this._getEffectiveLifetimeMs()) this._finish(nowMs);
  }

  launchProjectile(projectile) {
    if (!this.active || !this.empowered || !projectile) return false;
    this.shotsFired += 1;
    this.lastConsumedBreakCharge = this.storedBreakCharge;
    this.storedBreakCharge = 0;
    this.projectileImpacts += Math.max(0, projectile.impactedCount || 0);
    this.projectileDestroyed += Math.max(0, projectile.destroyedCount || 0);
    const destroyed = Math.max(0, projectile.destroyedCount || 0);
    this.storedBreakCharge = Math.min(
      Math.max(0, Number(this.definition.breakChargeMaximum) || 0),
      destroyed * Math.max(0, Number(this.definition.breakChargePerDestroyedTile) || 0),
    );
    this.earnedLifetimeMs = Math.min(
      Math.max(0, Number(this.definition.lifetimeGainCapMs) || 0),
      this.earnedLifetimeMs
        + destroyed * Math.max(0, Number(this.definition.lifetimeGainPerDestroyedTileMs) || 0),
    );
    const anchor = this.getAnchor();
    const angle = Math.atan2(projectile.direction.y, projectile.direction.x)
      * 180 / Math.PI;
    const spawnOffset = (Number(this.definition.projectileSpawnOffsetTiles) || 0)
      * this.tileSize;
    const origin = {
      x: anchor.x + projectile.direction.x * spawnOffset,
      y: anchor.y + projectile.direction.y * spawnOffset,
    };
    const paletteIndex = (this.shotsFired - 1) % this.vfx.paletteCount;
    this.lastProjectilePalette = this.vfx.getPalette(paletteIndex).id;
    this.paletteHistory.push(this.lastProjectilePalette);
    if (this.paletteHistory.length > 12) this.paletteHistory.shift();
    this.vfx.spawnLaunch(origin, angle, paletteIndex);
    const visualPaths = projectile.visualPaths?.length > 0
      ? projectile.visualPaths
      : (projectile.endTiles || [projectile.targetTile]).map(endTile => ({
          lane: endTile?.lane || 0,
          transitions: [],
          endTile,
        }));

    for (const path of visualPaths) {
      if (!path?.endTile) continue;
      const sprite = this._createProjectileVisual(origin, angle, paletteIndex);
      this.projectiles.add(sprite);
      this._launchVisualPath(sprite, path, paletteIndex);
    }

    const grouped = new Map();
    for (const hit of projectile.hits || []) {
      const lane = Number(hit.lane) || 0;
      if (!grouped.has(lane)) grouped.set(lane, []);
      grouped.get(lane).push(hit);
    }
    for (const hits of grouped.values()) {
      for (const hit of hits) {
        if (hit.result && hit.result.success !== true) continue;
        this._spawnImpact(hit, projectile, paletteIndex);
      }
    }
    return true;
  }

  _createProjectileVisual(anchor, angle, paletteIndex) {
    const sprite = this.scene.add.image(
      anchor.x,
      anchor.y,
      this.vfx.getProjectileAssetKey(paletteIndex),
    )
      .setBlendMode(Phaser.BlendModes.ADD)
      .setDepth(CELESTIAL_ENGINE_CONFIG.fx.worldDepth + 2);
    sprite.angle = angle;
    return sprite;
  }

  _launchVisualPath(sprite, path, paletteIndex) {
    const transitions = Array.isArray(path.transitions)
      ? path.transitions.slice().sort((a, b) => a.distance - b.distance)
      : [];
    const waypoints = [...transitions];
    const endTile = path.endTile;
    const last = waypoints.at(-1);
    if (!last || last.tx !== endTile.tx || last.ty !== endTile.ty) {
      waypoints.push(endTile);
    }
    const firstStateIndex = transitions[0]?.projectileStateIndex
      ?? endTile.projectileStateIndex
      ?? 0;
    this.vfx.applyState(sprite, firstStateIndex);

    const totalDistance = Math.max(1, Number(endTile.distance) || 1);
    const totalTravelMs = this._getTravelMs(totalDistance);
    let previousDistance = 0;
    let currentStateIndex = firstStateIndex;
    let waypointIndex = 0;
    const advance = () => {
      if (!this.projectiles.has(sprite)) return;
      const waypoint = waypoints[waypointIndex];
      if (!waypoint) {
        this._fadeProjectile(sprite);
        return;
      }
      const distance = Math.max(previousDistance + 1, Number(waypoint.distance) || 1);
      const duration = Math.max(
        1,
        Math.round(totalTravelMs * (distance - previousDistance) / totalDistance),
      );
      const fx = CELESTIAL_ENGINE_CONFIG.fx.stellarRage;
      const targetAlpha = fx.projectileAlpha
        + (fx.projectileEndAlpha - fx.projectileAlpha)
          * Math.min(1, distance / totalDistance);
      this.scene.tweens.add({
        targets: sprite,
        x: waypoint.tx * this.tileSize + this.tileSize / 2,
        y: waypoint.ty * this.tileSize + this.tileSize / 2,
        alpha: targetAlpha,
        duration,
        ease: "Linear",
        onComplete: () => {
          const nextStateIndex = waypoint.projectileStateIndex ?? firstStateIndex;
          if (nextStateIndex !== currentStateIndex) {
            this.vfx.spawnStateBurst(
              waypoint,
              sprite.angle,
              nextStateIndex,
              paletteIndex,
            );
          }
          this.vfx.applyState(sprite, nextStateIndex);
          sprite.setAlpha(targetAlpha);
          currentStateIndex = nextStateIndex;
          previousDistance = distance;
          waypointIndex += 1;
          advance();
        },
      });
    };
    advance();
  }

  _fadeProjectile(sprite) {
    const duration = CELESTIAL_ENGINE_CONFIG.fx.stellarRage.projectileFadeOutMs;
    this.scene.tweens.add({
      targets: sprite,
      scaleX: sprite.scaleX * 1.06,
      scaleY: sprite.scaleY * 0.84,
      alpha: 0,
      duration,
      ease: "Power2.out",
      onComplete: () => this._releaseProjectile(sprite),
    });
  }

  _getTravelMs(distance) {
    return Math.max(
      this.definition.projectileMinimumTravelMs,
      Math.min(
        this.definition.projectileMaximumTravelMs,
        distance * this.definition.projectileTravelMsPerTile,
      ),
    );
  }

  _spawnImpact(hit, projectile, paletteIndex) {
    const path = projectile.visualPaths?.find(
      candidate => Number(candidate.lane) === Number(hit.lane),
    );
    const totalDistance = Math.max(1, Number(path?.endTile?.distance)
      || Number(hit.distance) || 1);
    const delay = Math.round(
      this._getTravelMs(totalDistance)
      * Math.max(0, Number(hit.distance) || 0)
      / totalDistance,
    );
    const angle = Math.atan2(projectile.direction.y, projectile.direction.x)
      * 180 / Math.PI;
    this.vfx.spawnImpact(hit, paletteIndex, delay, angle);
  }

  _releaseProjectile(projectile) {
    this.projectiles.delete(projectile);
    projectile?.destroy?.();
  }

  getBuffSnapshot(nowMs) {
    const currentMs = Number.isFinite(Number(nowMs))
      ? Number(nowMs)
      : this.budget.startedAtMs;
    const ageMs = Math.max(0, currentMs - this.budget.startedAtMs);
    const lifetimeMs = this._getEffectiveLifetimeMs();
    const remainingMs = Math.max(0, lifetimeMs - ageMs);
    const empowered = this.empowered && ageMs < lifetimeMs;
    const nextShot = this.shotsFired + 1;
    const resonantEvery = Math.max(0, Math.floor(Number(this.definition.resonantEveryShots) || 0));
    const resonantReady = resonantEvery > 0 && nextShot % resonantEvery === 0;
    const finalWindow = empowered
      && Number(this.definition.finalWindowMs) > 0
      && remainingMs <= Number(this.definition.finalWindowMs);
    const projectileDamageMultiplier = roundHundredth(
      this.definition.projectileDamageMultiplier
        + this.storedBreakCharge
        + (resonantReady ? Number(this.definition.resonantDamageBonus) || 0 : 0),
    );
    const projectileSideLanes = this.definition.projectileSideLanes
      + (resonantReady ? Math.max(0, Number(this.definition.resonantSideLanes) || 0) : 0)
      + (finalWindow ? Math.max(0, Number(this.definition.finalWindowSideLanes) || 0) : 0);
    const states = this.definition.projectileStates || [];
    const maximumStateDamage = states.reduce(
      (maximum, state) => Math.max(maximum, Number(state.damageMultiplier) || 1),
      1,
    );
    const vfx = this.vfx?.getSnapshot?.() || {};
    return {
      active: empowered,
      empowered,
      projectileEnabled: empowered && this.definition.projectileEnabled === true,
      engineId: this.budget.engineId,
      activationId: this.budget.activationId,
      ageMs,
      lifetimeMs,
      remainingMs,
      impacts: this.projectileImpacts,
      maxImpacts: 0,
      bounces: 0,
      maxBounces: 0,
      redirects: 0,
      maxRedirects: 0,
      uniqueTargets: 0,
      projectileInfiniteRange: this.definition.projectileInfiniteRange === true,
      projectileRangeTiles: this.definition.projectileRangeTiles,
      projectileSafetyMaxTiles: this.definition.projectileSafetyMaxTiles,
      projectileDamageMultiplier,
      projectileMaximumDamageMultiplier: roundHundredth(
        projectileDamageMultiplier * maximumStateDamage,
      ),
      projectileStates: states,
      projectileStateCount: states.length,
      projectileSideLanes,
      projectilePassesGeodeWalls: this.definition.projectilePassesGeodeWalls,
      shotsFired: this.shotsFired,
      projectileImpacts: this.projectileImpacts,
      projectileDestroyed: this.projectileDestroyed,
      storedBreakCharge: roundHundredth(this.storedBreakCharge),
      lastConsumedBreakCharge: roundHundredth(this.lastConsumedBreakCharge),
      earnedLifetimeMs: this.earnedLifetimeMs,
      resonantReady,
      nextShot,
      finalWindow,
      playerVisualCount: this.playerVisualCount,
      liveVfxCount: vfx.liveVfxCount || 0,
      launchFlashCount: vfx.launchFlashCount || 0,
      stateBurstCount: vfx.stateBurstCount || 0,
      scheduledImpactCount: vfx.scheduledImpactCount || 0,
      impactMomentCount: vfx.impactMomentCount || 0,
      projectilePaletteCycle: vfx.paletteIds || [],
      lastProjectilePalette: this.lastProjectilePalette,
      paletteHistory: [...(this.paletteHistory || [])],
    };
  }

  getSnapshot(nowMs) {
    return this.getBuffSnapshot(nowMs);
  }

  _getEffectiveLifetimeMs() {
    return Math.max(1, Number(this.definition.lifetimeMs) || 1)
      + Math.max(0, Number(this.earnedLifetimeMs) || 0);
  }

  _finish(nowMs) {
    if (!this.active || this.finishing) return;
    this.finishing = true;
    this.empowered = false;
    this._complete(nowMs);
  }

  _complete(nowMs) {
    if (!this.active) return;
    const health = this.getBuffSnapshot(nowMs);
    this.active = false;
    this._destroyVisual();
    this.onComplete?.("projectile-buff-ended", health);
  }

  _destroyVisual() {
    for (const projectile of this.projectiles || []) {
      this.scene.tweens?.killTweensOf?.(projectile);
      projectile.destroy?.();
    }
    this.projectiles?.clear?.();
    this.vfx?.destroy?.();
  }

  destroy() {
    this.active = false;
    this.empowered = false;
    this._destroyVisual();
  }
}

